// Focus spells, including focus cantrips.

export const FOCUS_SPELLS = [
  { name: 'Agile Feet', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'The blessings of your god make your feet faster and your movements more fluid. You gain a +5-foot status bonus to your Speed and ignore difficult terrain. As part of casting agile feet, you can Step, Stride, or Tumble Through; you can instead Burrow, Climb, Fly, or Swim if you have the appropriate Speed.', duration: 'until the end of the current turn', action: '1' },
  { name: 'Allegro', level: 7, cantrip: true, focus: true, tradition: 'Bard', book: 'player-core', desc: 'You perform rapidly, speeding up your ally. The ally becomes quickened and can use the additional action to Strike, Stride, or Step.', range: '30 feet', target: '1 ally', action: '1' },
  { name: 'Animal Feature', level: 2, focus: true, tradition: 'Ranger', book: 'player-core', desc: 'Without fully transforming your body, you gain one animalistic feature, which you select from the list below each time you Cast the Spell. Cat Eyes You gain low-light vision. Claws You gain a claw attack that deals 1d6 slashing damage and has the agile, finesse, and unarmed traits. Jaws You gain a jaws attack that deals 1d8 piercing damage and has the unarmed trait.', action: '1' },
  { name: 'Appearance of Wealth', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You create a brief vision of immense wealth filling the spell’s area. Each creature within 20 feet of the area that could be enticed by material wealth must attempt a Will saving throw. A creature that enters the area automatically disbelieves the illusion, and disbelieving the illusion ends any fascinated condition imposed by the spell. As long as you Sustain the spell, other creatures react to the treasure like they would any other illusion, but they are not at risk of becoming fascinated. Critical Success The creature disbelieves the illusion and is unaffected by it. Success The creature is fascinated by the wealth until it has completed its first action on its next turn. Failure The creature is fascinated by the illusion.', range: '30 feet', area: '5-foot burst', duration: 'sustained up to 1 minute', action: '2' },
  { name: 'Artistic Flourish', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You transform the target into a form that more closes matches your creative vision. It’s clearly the same item, but with aesthetic details you choose. The target is a beautiful and impressive piece for its new quality, but the effect is obviously magical and temporary, so its monetary value doesn’t change. If you’re an expert in Crafting, the item grants a +1 item bonus to attack rolls if it’s a weapon or skill checks if it’s a skill tool. When you Cast this Spell, any previous casting ends.', range: '15 feet', target: '1 item or work of art that fits entirely within the range', action: '2' },
  { name: 'Athletic Rush', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'Your body fills with physical power and skill. You gain a +10- foot status bonus to Speed and a +2 status bonus to Athletics checks. As a part of Casting this Spell, you can use a Stride, Leap, Climb, or Swim action. The spell’s bonuses apply during that action.', duration: '1 round', action: '1' },
  { name: 'Bit of Luck', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You tilt the scales of luck slightly to protect a creature from disaster. When the target would attempt a saving throw, it can roll twice and use the better result. Once it does this, the spell ends. If you cast bit of luck again, any previous bit of luck you cast that’s still in effect ends. After a creature has been targeted with bit of luck, it becomes temporarily immune for 24 hours.', range: '30 feet', target: '1 willing creature', duration: '1 minute', action: '2' },
  { name: 'Blood Ward', level: 1, focus: true, tradition: 'Witch', book: 'player-core', desc: 'Your patron’s aegis descends to shield a target from harm. Designate one of the following creature traits: aberration, animal, beast, celestial, construct, dragon, elemental, fey, fiend, fungus, monitor, ooze, plant, or undead. The target gains a +1 status bonus to its saving throws and AC against creatures with that trait.', range: '30 feet', target: '1 creature', duration: 'sustained up to 1 minute', action: '1', heightened: "(5th) The status bonus increases to +2.", heightenAt: [5] },
  { name: 'Cackle', level: 1, focus: true, tradition: 'Witch', book: 'player-core', desc: 'With a quick burst of laughter, you prolong a magical effect you created. You Sustain a spell.', action: 'F' },
  { name: 'Captivating Adoration', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You become intensely entrancing, and creatures are distracted by you as long as they remain within the area. You can exclude any creatures you choose from the effects. If a creature is in the aura when you Cast the Spell or when it enters the aura for the first time, it must attempt a Will saving throw. If a creature leaves and reenters, it uses the results of its original save. Critical Success The creature is unaffected and temporarily immune for 1 hour. Success The creature is fascinated with you for its next action, then is temporarily immune for 1 hour. Failure The creature is fascinated with you. Critical Failure The creature is fascinated with you, and its attitude toward you improves by one step.', area: '15-foot emanation', action: '2' },
  { name: 'Charming Push', level: 1, focus: true, tradition: 'Wizard', book: 'player-core', desc: 'You push at the target’s mind to deflect their ire. The target must attempt a Will save. Critical Success The target is unaffected. Success The target takes a –1 circumstance penalty to attack rolls and damage rolls against you. Failure The target can’t use hostile actions against you. Critical Failure The target is stunned 1 and can’t use hostile actions against you.', range: '30 feet', target: '1 creature', duration: 'until the start of your next turn', action: '1' },
  { name: 'Charming Touch', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You infuse your target with attraction, causing it to act friendlier toward you. The target attempts a Will save. It gains a +4 circumstance bonus to this save if you or your allies recently threatened or were hostile to it. Critical Success The target is unaffected and aware you tried to charm it. Success The target is unaffected but thinks your spell was something harmless instead of charming touch, unless it identifies the spell (see Identifying Spells on page 303). Failure The target’s attitude becomes friendly toward you. If it was friendly, it becomes helpful. It can’t use hostile actions against you. If you use a hostile action against the target, the spell ends. You can Dismiss the spell. After the spell ends, the target doesn’t necessarily realize it was charmed unless its friendship with you or the actions you convinced it to take clash with its expectations. If it doesn’t realize you charmed it, you could potentially convince it to continue being your friend via mundane means. Critical Failure As failure, but the target is helpful.', range: 'touch', target: '1 creature that could find you attractive', duration: '10 minutes', action: '1' },
  { name: 'Clinging Ice', level: 1, cantrip: true, focus: true, tradition: 'Witch', book: 'player-core', desc: 'Freezing sleet and heavy snowfall collect on the target’s feet and legs, dealing 1d4 cold damage and other effects depending on its Reflex save. Critical Success The target is unaffected. Success The target takes half damage. Failure The target takes full damage and a –5-foot circumstance penalty to its Speeds until the spell ends. Critical Failure The target takes double damage and a –10-foot circumstance penalty to its Speeds until the spell ends.', damage: '1d4', range: '30 feet', target: '1 creature', action: '1', heightened: "(+1) The damage increases by 1d4.", heightenStep: 1, heightenDice: '1d4' },
  { name: 'Cloak of Shadow', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You drape the target in a mantle of swirling shadows that make it harder to see. The cloak reduces bright light within a 20-foot emanation to dim light. This is a form of magical darkness and can therefore overcome non-magical light or attempt to counteract magical light. The target can use concealed condition gained from the shadows to Hide, though observant creatures can still follow the moving aura of shadow, making it difficult for the target to become completely undetected. The target can use an Interact action to remove the cloak and leave it behind as a decoy, where it remains, reducing light for the rest of the spell’s duration. If anyone picks up the cloak after it’s been removed by the original target, the cloak evaporates and the spell ends.', range: 'touch', target: '1 willing creature', duration: '1 minute', action: '1' },
  { name: 'Commanding Lash', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'With the threat of more pain, you compel a creature you’ve recently harmed. You issue a command to the target, with the effects of the spell command. If the target is frightened, stupefied, or taking persistent damage, it takes a –2 circumstance penalty to the save. Regardless of the result, the target is then temporarily immune for 1 hour.', range: '100 feet', target: 'A creature you dealt damage to on your most recent action.', action: '1' },
  { name: 'Community Restoration', level: 4, focus: true, tradition: 'Wizard', book: 'player-core', desc: 'When you use your magic to support your allies, shared strength bolsters you all. You gain 2 temporary Hit Points per rank of the triggering spell, and can grant an equal number divided as you choose among allies affected by the triggering spell. These temporary Hit Points last for 1 minute.', action: 'R' },
  { name: 'Competitive Edge', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'Your competitiveness drives you to prove yourself against the opposition. You gain a +1 status bonus to attack rolls and skill checks. If an enemy within 20 feet critically succeeds at an attack roll or skill check, your status bonus increases to +3 for attack rolls or that specific skill check (whichever the foe critically succeeded at) for 1 round.', action: '1' },
  { name: 'Cornucopia', level: 1, focus: true, tradition: 'Druid', book: 'player-core', desc: 'Vines twine into a wicker horn in your hands, and out spills a single fruit, nut, or similar small bit of produce. A creature who eats the produce with an Interact action regains 1d6+4 HP. The cornucopia, as well as any unconsumed pieces of fruit, wither away at the end of the duration.', duration: '10 minutes', damage: '1d6+4', action: '2', heightened: "(+1) The cornucopia produces an additional piece of food. A creature can consume any amount of food from the same casting with a single Interact action. Eating six pieces of produce from the cornucopia gives as much nourishment as one square meal for a typical human.", heightenStep: 1 },
  { name: 'Counter Performance', level: 1, focus: true, tradition: 'Bard', book: 'player-core', desc: 'Your performance protects you and your allies. Roll a Performance check for a type you know—it must be an auditory performance if the trigger was auditory or a visual one for a visual trigger, and this action gains the traits for the type of performance. You and allies in the area can use the better result between your Performance check and the saving throw.', area: '60-foot emanation', action: 'R' },
  { name: 'Courageous Anthem', level: 1, cantrip: true, focus: true, tradition: 'Bard', book: 'player-core', desc: 'You inspire yourself and your allies with words or tunes of encouragement. You and all allies in the area gain a +1 status bonus to attack rolls, damage rolls, and saves against fear effects.', area: '60-foot emanation', action: '1' },
  { name: 'Creative Splash', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'A deluge of paint or colorful illusions descend on the area, reflecting your personal creative specialty. Roll 1d4 to determine the color of the illusion. Each creature in the area must succeed at a Will save or take the effect listed on the table for the color. Creative Splash 1d4 Color Failure Critical Failure 1 White Dazzled 1 round Dazzled 1 minute 2 Red Enfeebled 1 for 1 round Enfeebled 2 for 1 round 3 Yellow Frightened 1 Frightened 2 4 Blue Clumsy 1 for 1 round Clumsy 2 for 1 round', range: '30 feet', area: '5-foot burst', duration: 'varies', action: '2' },
  { name: 'Cry of Destruction', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'Your voice booms, smashing what’s in front of you. Each creature and unattended object in the area takes 1d8 sonic damage. If you already dealt damage to an enemy this turn with a Strike or spell, increase the damage dice from this spell to d12s.', damage: '1d8', area: '15-foot cone', action: '2', heightened: "(+1) The damage increases by 1d8.", heightenStep: 1, heightenDice: '1d8' },
  { name: 'Curse of Death', level: 5, focus: true, tradition: 'Witch', book: 'player-core', desc: 'Your patron wraps a hand around your target’s heart. The target must attempt a Fortitude saving throw. Regardless of the result, the target is temporarily immune to all curses of death for 1 day. Critical Success The target is unaffected. Success The target is afflicted with the curse of death at stage 1, and the stage of the curse can’t increase beyond stage 1. Failure The target is afflicted with the curse of death at stage 1. Critical Failure The target is afflicted with the curse of death at stage 2. Curse of Death (curse, death, void) This curse ends when the spell ends; Stage 1 4d6 void damage and fatigued (1 round); Stage 2 8d6 void damage and fatigued (1 round); Stage 3 12d6 void damage and fatigued (1 round); Stage 4 death', range: '30 feet', target: '1 creature', action: '2' },
  { name: 'Darkened Sight', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You infuse a creature’s vision with darkness. It receives greater darkvision, allowing it to see even in magical darkness.', range: '60 feet', target: '1 creature', action: '2' },
  { name: 'Dazzling Flash', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You raise your religious symbol and create a blinding flash of light. Each creature in the area must attempt a Fortitude save. Critical Success The creature is unaffected. Success The creature is dazzled for 1 round. Failure The creature is blinded for 1 round and dazzled for 1 minute. The creature can spend an Interact action rubbing its eyes to end the blinded condition. Critical Failure The creature is blinded for 1 round and dazzled for 1 hour.', area: '15-foot cone', action: '2', heightened: "(3rd) The area increases to a 30-foot cone.", heightenAt: [3] },
  { name: 'Death\'s Call', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'Seeing another pass from this world invigorates you. You gain temporary Hit Points equal to the triggering creature’s level plus your spellcasting attribute modifier. If the triggering creature was undead, double the number of temporary Hit Points you gain. These last for the duration of the spell, and the spell ends if all the temporary Hit Points are depleted earlier.', duration: '1 minute', action: 'R' },
  { name: 'Deceiver\'s Cloak', level: 3, focus: true, tradition: 'Witch', book: 'player-core', desc: 'Your patron drapes a cloak of illusion about you, making you appear as another creature of the same body shape with roughly similar height and weight as yourself. This has the effects of 3rd-rank illusory disguise.', action: '2' },
  { name: 'Delusional Pride', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You make the target overconfident, leading it to ascribe failure to external factors. The target attempts a Will save to determine the spell’s duration and is temporarily immune for 24 hours regardless of the save’s result. Critical Success The target is unaffected. Success The duration is 1 round. If the target fails at an attack roll or skill check, it takes a –1 status penalty to attack rolls and skill checks until the end of its turn (or the end of its next turn, if it attempted the roll outside its turn). If the creature fails a second time while taking this penalty, the penalty increases to –2. Failure As success, but the duration is 10 minutes. Critical Failure As success, but the duration is 24 hours.', range: '30 feet', target: '1 creature', action: '2' },
  { name: 'Destructive Aura', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'Swirling sands of divine devastation surround you, weakening the defenses of all they touch. Reduce the resistances of yourself and creatures in the area by 2.', area: '15-foot emanation', action: '2' },
  { name: 'Dirge of Doom', level: 3, cantrip: true, focus: true, tradition: 'Bard', book: 'player-core', desc: 'Enemies within the area are frightened 1. They can’t reduce their frightened value below 1 while they remain in the area.', area: '30-foot emanation', action: '1' },
  { name: 'Discern Secrets', level: 1, cantrip: true, focus: true, tradition: 'Witch', book: 'player-core', desc: 'Your patron deigns to whisper a few secrets. The target can Recall Knowledge, Seek, or Sense Motive as a free action. The target gains a +1 status bonus to the statistic used for the roll (a skill or Perception) on the roll and as long as you Sustain the spell. The target is temporarily immune to discern secrets for 1 minute.', range: '30 feet', target: '1 creature', action: '1' },
  { name: 'Disperse into Air', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'After taking the triggering damage, you transform into air. Until the end of the current turn, you can’t be attacked or targeted, you don’t take up space, you can’t act, and any auras or emanations you have are suppressed. At the end of the turn, you re-form in any space you can occupy within 15 feet of where you were when you dispersed. Any auras or emanations you had are restored as long as their duration didn’t run out while you were dispersed.', action: 'R' },
  { name: 'Downpour', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You call forth a torrential downpour, which extinguishes non-magical flames. Creatures in the area are concealed and gain fire resistance 10. Creatures outside the area are concealed to those inside the area. If a creature with weakness to water ends its turn in the area, the downpour triggers its weakness.', range: '120 feet', area: '30-foot burst', action: '2' },
  { name: 'Dreamer\'s Call', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You create a vivid, illusory daydream drawn from the images of the target’s dreams. The daydream appears in an unoccupied space in range, and you attempt to draw the target toward it. Critical Success The target is unaffected. Success The target’s attention wavers. It becomes fascinated by the daydream. Failure The target is fascinated with the daydream and pursues a course of action you choose as its first action after you Cast the Spell: approach the daydream, run away from it (as the fleeing condition), Release what it’s holding as an offering, or Drop Prone in obeisance. Critical Failure As failure, but the target follows the course of action for as many actions as possible for the spell’s duration, and does nothing else.', range: '30 feet', target: '1 creature', action: '2' },
  { name: 'Earthworks', level: 1, focus: true, tradition: 'Wizard', book: 'player-core', desc: 'With a ripple of earth, you raise small barriers from the ground. The ground in the area becomes difficult terrain. The spell’s area is a 5-foot burst if you spent 1 action to cast it, a 10-foot burst if you spent 2 actions, or a 15-foot burst if you spent 3 actions. A creature can Interact to clear the barriers from one 5-foot square adjacent to it.', range: '60 feet', area: '5-foot burst or more', duration: '1 minute', action: '1-3', heightened: "(4th) You pull the barriers to float in the air, causing the spell to function as difficult terrain for flying creatures.", heightenAt: [4] },
  { name: 'Elemental Betrayal', level: 1, focus: true, tradition: 'Witch', book: 'player-core', desc: 'Your patron uses its superior command of the elements, empowering them to undermine your foe. When you Cast this Spell, choose air, earth, metal, fire, water, or wood. The target gains weakness 2 to that trait.', range: '30 feet', target: '1 creature', duration: 'sustained up to 1 minute', action: '1', heightened: "(+2) Increase the weakness by 1.", heightenStep: 2 },
  { name: 'Enduring Might', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'Your own might mingles with divine power to protect you from harm. You gain resistance equal to 8 plus your Strength modifier against all damage from the triggering attack or effect.', action: 'R' },
  { name: 'Energy Absorption', level: 4, focus: true, tradition: 'Wizard', book: 'player-core', desc: 'You’re used to mitigating the damage done by bombs, siege engines, and magical artillery. You gain resistance 15 to your choice of acid, cold, electricity, or fire damage from the triggering effect. The resistance applies only to the triggering effect’s initial damage.', action: 'R' },
  { name: 'Enlarge Companion', level: 2, focus: true, tradition: 'Ranger', book: 'player-core', desc: 'Your animal companion grows much larger, towering over its foes in battle. Your animal companion becomes Large, gaining the effects of a 2nd-rank enlarge spell.', range: '30 feet', target: 'your animal companion', action: '2' },
  { name: 'Ephemeral Tracking', level: 3, focus: true, tradition: 'Ranger', book: 'player-core', desc: 'You can look at currents in the air and water and see tracks that you can follow just as you would on land. You can use Survival to Track through both air and water, noticing aerial or aquatic “tracks” of all creatures who passed nearby in the last hour. It’s more difficult to Track in this way: the DC to Track through air or water is always at least 30, or higher after precipitation or wind (in the air) or heavy tides or currents (in the water). It’s possible to Cover Tracks against this spell, but creatures might not realize they need to do so.', action: '2' },
  { name: 'Eradicate Undeath', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'A massive deluge of life energy causes the undead to fall apart. Each undead creature in the area takes 4d12 vitality damage.', damage: '4d12', area: '30-foot cone', action: '2', heightened: "(+1) The damage increases by 1d12.", heightenStep: 1, heightenDice: '1d12' },
  { name: 'Evil Eye', level: 1, cantrip: true, focus: true, tradition: 'Witch', book: 'player-core', desc: 'Your patron’s resentment manifests in a baleful, envious gaze. The target becomes sickened 1 if it fails a Will save (or sickened 2 on a critical failure). This condition value can’t be reduced below 1 while the spell is active and you can see the target.', range: '30 feet', target: '1 creature', action: '1' },
  { name: 'Face in the Crowd', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'While in a crowd of roughly similar creatures, your appearance becomes bland and nondescript. You gain a +2 status bonus to Deception and Stealth checks to go incognito among the crowd, and you ignore difficult terrain caused by the crowd. This counts as setting up a disguise for the Impersonate use of Deception and you add your level even if you’re untrained.', duration: '1 minute', action: '1', heightened: "(3rd) The spell gains a range of 10 feet and can target up to 10 creatures.", heightenAt: [3] },
  { name: 'Fatal Aria', level: 10, focus: true, tradition: 'Bard', book: 'player-core', desc: 'You perform music so perfect that the target may die of joy or sorrow. Once targeted, the creature becomes temporarily immune for 1 minute. The effect of the spell depends on the target’s level and current Hit Points. 16th or Lower The target dies instantly. 17th If the target has 50 Hit Points or fewer, it dies instantly; otherwise, it drops to 0 Hit Points and becomes dying 1. 18th or Higher The target takes 50 damage. If this brings it to 0 Hit Points, it dies instantly.', range: '30 feet', target: '1 creature', action: '1' },
  { name: 'Fire Ray', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'A blazing band of fire arcs through the air, lighting your opponent and the ground they stand upon on fire. Make a spell attack roll against the target’s AC. The ray deals 2d6 fire damage on a hit (or double damage on a critical hit). On any result other than a critical failure, the ground in the target’s space catches fire, dealing 1d6 fire damage to each creature that ends its turn in one of the squares.', damage: '2d6', range: '60 feet', target: '1 creature', duration: 'until the end of the target\'s next turn', action: '2', heightened: '(+1) The ray’s initial damage increases by 2d6, and the fire damage dealt by the burning space increases by 1d6.', heightenStep: 1, heightenDice: '2d6' },
  { name: 'Flame Barrier', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You swiftly deflect incoming flames. The target gains fire resistance 15 against the triggering effect.', range: '30 feet', target: 'the creature that would take fire damage', action: 'R' },
  { name: 'Force Bolt', level: 1, focus: true, tradition: 'Wizard', book: 'player-core', desc: 'You fire an arrow-shaped bolt of force, one of the most common and reliable forms of battle magic. It automatically hits and deals 1d4+1 force damage to the target.', damage: '1d4+1', range: '30 feet', target: '1 creature', action: '1', heightened: "(+2) The damage increases by 1d4+1.", heightenStep: 2, heightenDice: '1d4+1' },
  { name: 'Fortify Summoning', level: 1, focus: true, tradition: 'Wizard', book: 'player-core', desc: 'As you call a creature to your side, your magic transforms its body, heightening its ferocity and fortifying its resilience. The target gains a +1 status bonus to all checks and DCs (including its AC) for the duration of its summoning, up to 1 minute.', range: '30 feet', target: '1 creature you summoned', action: '1' },
  { name: 'Fortissimo Composition', level: 4, focus: true, tradition: 'Bard', book: 'player-core', desc: 'You call upon your muse to greatly increase the benefits you provide with your courageous anthem, rallying anthem, or song of strength composition. If your next action is to cast one of these compositions, attempt a Performance check. The DC is usually the highest Will DC of the composition’s targets, but the GM can assign a different DC based on the circumstances. The effect of your composition depends on the result of your check. Critical Success The status bonus from your composition increases to +3. Success The status bonus from your composition increases to +2. Failure Your composition provides only its normal bonus of +1, but you don’t spend the Focus Point for casting this spell.', action: 'F' },
  { name: 'Glimpse the Truth', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'Divine insight lets you see things as they are, unveiled by attempts to magically cloak the truth. The GM attempts a secret counteract check against each illusion that is at least partially within the area. Instead of counteracting the illusion, you see through it (for instance, if the check succeeds against an illusory disguise spell, you see the creature’s true form but illusory disguise doesn’t end). Each time a new illusion comes into the aura during the duration of the spell, the GM attempts a secret counteract check for that illusion.', area: '30-foot emanation', action: '1' },
  { name: 'Gravity Weapon', level: 1, focus: true, tradition: 'Ranger', book: 'player-core', desc: 'You build up gravitational force and funnel it into your blows, leading to more powerful attacks with blade and bow alike. On your first weapon Strike each round, you gain a status bonus to damage equal to twice the number of weapon damage dice.', duration: '1 minute', action: '1' },
  { name: 'Hand of the Apprentice', level: 1, focus: true, tradition: 'Wizard', book: 'player-core', desc: 'You take advantage of one of the most fundamental lessons of magic to levitate and propel your weapon. You hurl a held melee weapon with which you are trained at the target, making a spell attack roll. On a success, you deal the weapon’s damage as if you had hit with a melee Strike, but add your spellcasting attribute modifier to damage, rather than your Strength modifier. On a critical success, you deal double damage, and you add the weapon’s critical specialization effect. Regardless of the outcome, the weapon flies back to you and returns to your hand.', range: '500 feet', target: '1 creature', action: '1' },
  { name: 'Heal Animal', level: 1, focus: true, tradition: 'Druid', book: 'player-core', desc: 'You heal an animal’s wounds, restoring 1d8 Hit Points to the target. The number of actions spent Casting this Spell determines its effect. 1 Action The spell has a range of touch. 2 Actions (concentrate) The spell has a range of 30 feet and restores an additional 8 Hit Points to the target.', range: 'varies', target: '1 willing living animal', damage: '1d8', action: '1-2', heightened: "(+1) The amount of healing increases by 1d8, and the additional healing for the 2-action version increases by 8.", heightenStep: 1, heightenDice: '1d8' },
  { name: 'Heal Companion', level: 1, focus: true, tradition: 'Ranger', book: 'player-core', desc: 'You heal your animal companion’s wounds. You restore 1d10 Hit Points to your animal companion. The number of actions you spend Casting this Spell determines range and other parameters. 1 Action (manipulate) The spell has a range of touch. 2 Actions (concentrate, manipulate) The spell has a range of 30 feet and restores an additional 8 Hit Points to the target.', range: 'touch or 30 feet', target: 'your animal companion', damage: '1d10', action: '1-2', heightened: "(+1) The amount of healing increases by 1d10, and the additional healing for the 2-action version increases by 8.", heightenStep: 1, heightenDice: '1d10' },
  { name: 'Healer\'s Blessing', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'Your words bless a creature with an enhanced connection to vital energy. When the target regains Hit Points from a healing vitality spell, it regains 2 additional Hit Points. The target regains additional Hit Points from healer’s blessing only the first time it regains HP from a given healing spell, so a spell that heals the creature repeatedly over a duration would restore additional Hit Points only once, when they are first healed.', range: '30 feet', target: '1 willing living creature', duration: '1 minute', action: '1', heightened: "(+1) The additional healing increases by 2 HP.", heightenStep: 1 },
  { name: 'House of Imaginary Walls', level: 5, cantrip: true, focus: true, tradition: 'Bard', book: 'player-core', desc: 'You mime an invisible 10-foot-by-10-foot wall adjacent to you and within your reach. The wall is solid to those creatures that don’t disbelieve it, even incorporeal creatures. You and your allies can voluntarily believe the wall exists to continue to treat it as solid, for instance to climb onto it. A creature that disbelieves the illusion is temporarily immune to your house of imaginary walls for 1 minute. The wall doesn’t block creatures that didn’t see your visual performance, nor does it block objects. The wall has AC 10, Hardness equal to double the spell’s rank, and HP equal to quadruple the spell’s rank.', range: 'touch', action: '1' },
  { name: 'Hunter\'s Luck', level: 2, focus: true, tradition: 'Ranger', book: 'player-core', desc: 'You have a preternatural ability to remember details about your foes. Roll the triggering check twice and use the better result.', action: 'F' },
  { name: 'Hunter\'s Vision', level: 5, focus: true, tradition: 'Ranger', book: 'player-core', desc: 'Your target glows with a magical aura visible only to you and those who follow your lead. Your target is visible to you and others sharing your Hunt Prey benefits even if it wouldn’t normally be due to lighting or the concealed or invisible conditions, though cover from opaque objects still blocks your sight. You ignore the flat check against the target due to the concealed condition, and the target isn’t automatically hidden from you due to darkness or being invisible.', range: '30 feet', target: '1 hunted prey', action: '1' },
  { name: 'Hurtling Stone', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You evoke a magical stone and throw it, with divine guide to your aim. The stone deals 2d6 bludgeoning damage depending on your spell attack roll against the target’s AC. Critical Success The target takes double damage and you can push it up to 10 feet. Success The target takes full damage and you can push it up to 5 feet.', damage: '2d6', range: '60 feet', target: '1 creature', action: '1', heightened: "(+1) The stone's damage increases by 1d6.", heightenStep: 1, heightenDice: '1d6' },
  { name: 'Hymn of Healing', level: 1, focus: true, tradition: 'Bard', book: 'player-core', desc: 'Your glorious singing mends wounds and provides a temporary respite from harm. The target gains fast healing 2. When you Cast the Spell and the first time each round you Sustain the Spell, the target gains 2 temporary Hit Points, which last for 1 round.', range: '30 feet', target: 'you or 1 ally', duration: 'sustained up to 4 rounds', action: '2', heightened: "(+1) The fast healing and temporary Hit Points each increase by 2.", heightenStep: 1 },
  { name: 'Ignite Ambition', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You strengthen the target’s ambition, increase its resentment of its allies, and make its allegiances more susceptible to change. It must attempt a Will save. Critical Success The target is unaffected and realized you attempted to influence its reaction with magic. Success The target takes a –1 status penalty to its defenses against the triggering effect. This penalty is –2 if the target is being encouraged to advance its own ambitions. The target doesn’t realize you Cast the Spell on it. Failure As success, but the status penalty is –4 if the target is being encouraged to advance its own ambitions. Critical Failure As success, but the creature automatically follows a suggestion that advances its own ambitions.', range: '60 feet', target: 'one creature being influenced', action: 'R' },
  { name: 'Impaling Briars', level: 8, focus: true, tradition: 'Druid', book: 'player-core', desc: 'The ground within the area transforms into a mass of dangerous briars that assault and impede your foes. When you Cast the Spell and the first time you Sustain it each turn on subsequent rounds, select one of the following effects to occur in the area. Ensnare The briars clump around your foes, attempting to hold them in place. A foe within the area (or flying at most 20 feet above the area) must attempt a Reflex save. On a failure, it takes a –10-foot circumstance penalty to all Speeds for 1 round, and on a critical failure, it is immobilized for 1 round unless it Escapes. Impede The briars twist and writhe, making the entire area difficult terrain. Wall A wall of thorns appears in the area, lasting for 1 round. The wall is greater difficult terrain instead of difficult terrain. In addition, once per round you can direct the briars to impale any target in the area (or flying up to 20 feet above the area) that you can see by using a single action, which has the concentrate and manipulate traits. Make a spell attack roll. On a success, the target takes 10d6 piercing damage and takes a –10- foot circumstance penalty to all Speeds for 1 round; on a critical success, the target is immobilized for 1 round unless it Escapes.', damage: '10d6', area: '100-foot emanation', action: '3' },
  { name: 'Interdisciplinary Incantation', level: 4, focus: true, tradition: 'Wizard', book: 'player-core', desc: 'You gather the embers of another caster’s spell, using your understanding of unified magic to pick apart their formulas and incantations well enough to imitate the spell yourself, if only for a short time. Until the end of your next turn, you can Cast the triggering Spell by expending a wizard spell slot of the same rank. That caster’s spells can’t trigger your interdisciplinary incantation again for 24 hours.', action: 'R' },
  { name: 'Invisibility Cloak', level: 4, focus: true, tradition: 'Wizard', book: 'player-core', desc: 'You become invisible, with the same restrictions as the 2nd-rank invisibility spell.', action: '2' },
  { name: 'Know the Enemy', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You quickly remind yourself of useful information. Use a Recall Knowledge action, rolling the appropriate skill check to identify the triggering creature’s abilities. You can roll your check twice and use the better result.', action: 'R' },
  { name: 'Life Boost', level: 1, focus: true, tradition: 'Witch', book: 'player-core', desc: 'Life force from your patron floods into the target, ensuring they can continue doing your patron’s will for just a little longer. The target gains fast healing 2.', range: '30 feet', target: '1 creature', duration: '4 rounds', action: '1', heightened: "(+1) The fast healing increases by 2.", heightenStep: 1 },
  { name: 'Lingering Composition', level: 1, focus: true, tradition: 'Bard', book: 'player-core', desc: 'You add a flourish to your composition to extend its benefits. If your next action is to cast a cantrip composition with a duration of 1 round, attempt a Performance check. The DC is usually a standard-difficulty DC of a level equal to the highest-level target of your composition, but the GM can assign a different DC based on the circumstances. The effect depends on the result of your check. Critical Success The composition lasts 4 rounds. Success The composition lasts 3 rounds. Failure The composition lasts 1 round, but you don’t spend the Focus Point for casting this spell.', action: 'F' },
  { name: 'Localized Quake', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You shake the earth, toppling nearby creatures. Choose whether the spell’s area is a 15-foot emanation or a 15-foot cone when you cast it. Each creature in the area standing on solid ground takes 4d6 bludgeoning damage with a basic Reflex saving throw. A creature that fails its save also falls prone.', damage: '4d6', action: '2', heightened: "(+1) Increase the damage by 2d6.", heightenStep: 1, heightenDice: '2d6' },
  { name: 'Loremaster\'s Etude', level: 1, focus: true, tradition: 'Bard', book: 'player-core', desc: 'You call upon your muse’s deep mysteries, granting the target a greater ability to think and recall information. Roll the triggering Recall Knowledge skill check twice and use the higher result.', range: '30 feet', target: 'you or the triggering ally', action: 'F' },
  { name: 'Lucky Break', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'Reroll the saving throw and use the better result. You then become temporarily immune for 10 minutes.', action: 'R' },
  { name: 'Magic Hide', level: 1, focus: true, tradition: 'Ranger', book: 'player-core', desc: 'Your animal companion grows a thicker hide, matted fur, or a harder shell, granting it a +1 status bonus to AC.', range: '30 feet', target: 'your animal companion', duration: '1 minute', action: '1' },
  { name: 'Magic\'s Vessel', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'A creature becomes a divine receptacle for pure magical energy. The target gains a +1 status bonus to saving throws. Each time you Cast a Spell from your spell slots, you automatically Sustain this spell and grant its target resistance to damage from spells equal to the spell’s rank, until the start of your next turn.', range: 'touch', target: '1 creature', duration: 'sustained up to 1 minute', action: '1' },
  { name: 'Malicious Shadow', level: 3, focus: true, tradition: 'Witch', book: 'player-core', desc: 'Your patron warps the target’s shadow into a deadly form, such as strangling hands, a dangerous weapon, harrying runes, or the like. The shadow moves along with the target, always remaining within reach. When you Cast the Spell, and each time you Sustain it, the shadow Strikes the target. The shadow’s Strikes are melee spell attacks that deal 2d10 damage. You choose the type of damage (bludgeoning, piercing, or slashing) when you Cast the Spell. The shadow uses and contributes to your multiple attack penalty. The shadow doesn’t take up space, grant flanking, or have any other attributes a creature would. The shadow can’t make any attacks other than its Strike. The shadow vanishes if the target ceases to cast a shadow (usually if it moves into complete darkness or light). If another effect is controlling the target’s shadow when you cast malicious shadow, you can attempt to counteract that effect to temporarily take control of the shadow for malicious shadow’s duration.', damage: '2d10', range: '30 feet', target: '1 creature', action: '2', heightened: "(+2) The Strike damage increases by 1d10.", heightenStep: 2, heightenDice: '1d10' },
  { name: 'Malignant Sustenance', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You embed a seed of void energy in an undead creature, restoring its unnatural vigor over time. The target gains fast healing 7.', range: 'touch', target: '1 willing undead creature', action: '2' },
  { name: 'Moonbeam', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You shine a ray of moonlight. Make a spell attack roll. The beam of light deals 2d6 fire damage. This is silver damage for the purposes of weaknesses, resistances, and the like. Critical Success The beam deals double damage, and the target is dazzled for 1 minute. Success The beam deals full damage, and the target is dazzled for 1 round.', damage: '2d6', range: '120 feet', target: '1 creature', action: '2', heightened: "(+1) The ray's damage increases by 1d6.", heightenStep: 1, heightenDice: '1d6' },
  { name: 'Mystic Beacon', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'The next damaging or healing spell the target casts before the start of your next turn deals damage or restores Hit Points as if the spell were heightened 1 rank higher than its actual rank. This applies only to initial healing or damage when the spell is cast, not any ongoing effects. The spell otherwise functions at its actual rank. Once the target casts the spell, mystic beacon ends.', range: '30 feet', target: '1 willing creature', action: '1' },
  { name: 'Nature\'s Bounty', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'A palm-sized raw fruit or vegetable of your choice appears in your open hand. A creature can consume the food with an Interact action to regain 3d10+12 Hit Points and be nourished as if it had eaten a meal. If uneaten, the food crumbles to dust after 1 minute.', action: '1' },
  { name: 'Needle of Vengeance', level: 1, focus: true, tradition: 'Witch', book: 'player-core', desc: 'A long, jagged needle jabs into the target foe’s psyche whenever it tries to attack a creature your patron holds in special regard. Name yourself or one of your allies. The target takes 2 mental damage any time it uses a hostile action against the named creature, with a basic Will save.', range: '30 feet', target: '1 enemy', duration: 'sustained up to 1 minute', action: '1', heightened: "(+1) Increase the damage by 2.", heightenStep: 1 },
  { name: 'Nudge Fate', level: 1, cantrip: true, focus: true, tradition: 'Witch', book: 'player-core', desc: 'The barest spin of your patron’s spool is enough to alter fate. When the target fails an attack roll, skill check, or saving throw and a +1 status bonus would turn a critical failure into a failure, or failure into a success, you grant the target a +1 status bonus to the check retroactively, changing the outcome appropriately. The spell then ends. If you cast nudge fate while a previous casting of this hex is still in effect, the previous effect ends.', range: '30 feet', target: '1 creature', action: '1' },
  { name: 'Ode to Ouroboros', level: 5, focus: true, tradition: 'Bard', book: 'player-core', desc: 'Your ode staves off death. The target’s dying condition remains 1 below the value at which it dies. This doesn’t help prevent death from effects that kill the target without increasing its dying condition, such as disintegrate and death effects.', range: '60 feet', target: 'the triggering creature', action: 'R' },
  { name: 'Overstuff', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'Huge amounts of food and drink fill the target. It receives a full meal’s worth of nourishment and must attempt a Fortitude save. A target sickened by this spell takes a –10-foot status penalty to its Speed until it’s no longer sickened. Critical Success The target is unaffected. Success The target is sickened 1, but if it spends an action to end the condition, it succeeds automatically. Failure The target is sickened 1. Critical Failure The target is sickened 2.', range: '30 feet', target: '1 living creature', action: '2' },
  { name: 'Patron\'s Puppet', level: 1, focus: true, tradition: 'Witch', book: 'player-core', desc: 'At your unspoken plea, your patron temporarily assumes control over your familiar. You Command your familiar, allowing it to take its normal actions this turn. Your Command does not have the auditory or concentrate traits; your patron simply moves its agent directly.', action: 'F' },
  { name: 'Perfected Body', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'Your body’s perfection keeps you just a little bit healthier than most. You get a failure if you rolled a critical failure or a success if you rolled a failure.', action: 'R' },
  { name: 'Perfected Mind', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You meditate upon perfection to remove all distractions from your mind. Attempt a new Will save against one mental effect currently affecting you that required a Will save. Use the result of this new save to determine the outcome of the mental effect, unless the new save would have a worse result than the original save, in which case nothing happens. You can use perfected mind against a given effect only once.', action: '1' },
  { name: 'Personal Blizzard', level: 3, focus: true, tradition: 'Witch', book: 'player-core', desc: 'Your patron’s breath becomes a blizzard of obscuring, scouring ice that follows your target. The target attempts a Fortitude save. Critical Success The target is unaffected. Success The target takes 1d6 cold damage, and the spell ends. Failure The target takes 1d6 cold damage and 1d6 persistent cold damage. The persistent damage automatically ends when the spell ends. It is concealed to other creatures, and other creatures are concealed to it. Critical Failure As failure, but both the cold damage and the persistent cold damage are 2d6.', damage: '1d6', range: '30 feet', target: '1 creature', action: '1', heightened: "(+1) The cold damage and persistent cold damage increase by 1 (2 on a critical failure).", heightenStep: 1, heightenDice: '1' },
  { name: 'Phase Familiar', level: 1, focus: true, tradition: 'Witch', book: 'player-core', desc: 'Your patron momentarily recalls your familiar to the ether, shifting it from its solid, physical form into a ghostly version of itself. Against the triggering damage, your familiar gains resistance 5 to all damage and is immune to precision damage.', range: '60 feet', target: 'your familiar', action: 'R', heightened: "(+1) Increase the resistance by 2.", heightenStep: 1 },
  { name: 'Pied Piping', level: 10, focus: true, tradition: 'Bard', book: 'player-core', desc: 'Your performance enraptures listeners, compelling them to follow you. Each creature within the emanation must attempt a Will save when you Cast the Spell or the first time they enter the area, after which they become temporarily immune for 1 day. Once per turn, you can Sustain the composition to increase the emanation’s radius by 5 feet. You can Dismiss the spell. Critical Success The creature is unaffected. Success The creature is fascinated with you. Failure The creature is fascinated by you and uses all its actions to move toward you and compliment your performance. This effect ends if a hostile action is used against the affected creature. Critical Failure The target gains the minion trait and is controlled by you. This effect ends if a hostile action is used against the affected creature, or if you direct the creature to use any action that causes it harm.', action: '2' },
  { name: 'Precious Metals', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'Your deity blesses base metals to transform them into precious materials. The metal in the target transforms from its normal metal into cold iron, copper, gold, iron, silver, or steel. If the spell’s rank is 8th or higher, add adamantine and dawnsilver to the options. If you transform an object into copper, gold, or silver, its Hardness is reduced to 1. Otherwise, its Hardness is increased to 10 if it was lower. An item transmuted in this way deals damage according to its new material. For example, a steel sword transmuted to cold iron would deal additional damage to a creature with a weakness to cold iron. It can have other effects of the new material at the GM’s discretion. This change is clearly magical and temporary, so the item’s monetary value doesn’t change; you couldn’t transmute copper coins to gold and use them to purchase something.', range: 'touch', target: '1 metal shield or weapon, 1 suit of metal armor, or up to 1 Bulk of metal material (such as coins or metal-tipped ammunition)', action: '1' },
  { name: 'Primal Summons', level: 6, focus: true, tradition: 'Druid', book: 'player-core', desc: 'You enhance a summoned creature with the power of the elements. If your next action is to cast either summon animal or summon plant or fungus, choose air, earth, fire, metal, water, or wood; the creature you summon gains the corresponding abilities. Air The creature gains a fly Speed of 60 feet. Earth The creature gains a burrow Speed of 20 feet, reduces its land Speed by 10 feet (minimum 5 feet), and gains resistance 5 to physical damage. Fire The creature’s Strikes deal 1d6 extra fire damage, and it gains resistance 10 to fire and weakness 5 to cold and water. Metal The creature’s Strikes deal 1d6 extra electricity damage, and it gains resistance 5 to electricity. Water The creature gains a swim Speed of 60 feet, can spend 1 action after a melee attack to attempt a Shove (ignoring multiple attack penalty), and gains resistance 5 to fire. Wood The creature gains a climb Speed of 30 feet and resistance 2 to bludgeoning and piercing damage.', action: 'F' },
  { name: 'Protective Wards', level: 1, focus: true, tradition: 'Wizard', book: 'player-core', desc: 'You expand a ring of glyphs that shields your allies. You and any allies in the area gain a +1 status bonus to AC. Each time you Sustain the spell, the emanation’s radius increases by 5 feet, to a maximum of 30 feet.', area: '5-foot emanation', duration: 'sustained up to 1 minute', action: '1' },
  { name: 'Protector\'s Sacrifice', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You protect your ally by suffering in their stead. Reduce the damage the ally would take by 3. You redirect this damage to yourself, but your immunities, weaknesses, resistances and so on do not apply You aren’t subject to any conditions or other effects of whatever damaged your ally (such as poison from a venomous bite). Your ally is still subject to those effects even if you redirect all of the triggering damage to yourself.', range: '30 feet', action: 'R', heightened: "(+1) The damage you redirect increases by 3.", heightenStep: 1 },
  { name: 'Protector\'s Sphere', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'A protective aura emanates out from you, safeguarding you and your allies. You gain resistance 3 to all damage. Your allies also gain this resistance while in the aura.', area: '15-foot emanation', action: '2' },
  { name: 'Pulse of Civilization', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You tap into the zeitgeist of any settlements in range. You learn the names of the settlements. On all Lore checks to Recall Knowledge about those settlements or to Gather Information in or about those settlements, you gain a +2 status bonus and use your level as your proficiency bonus even if you’re untrained. When you Cast the Spell, you can immediately Recall Knowledge about one of the settlements using its Lore skill (such as Absalom Lore), which benefits from the bonus. If you cast pulse of civilization again, any previous casting ends.', range: '25 miles', action: '2' },
  { name: 'Pushing Gust', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'Giving the air a push, you buffet the target with a powerful gust of wind; it must attempt a Fortitude save. Critical Success The target is unaffected. Success The target is pushed 5 feet away from you. Failure The target is pushed 10 feet away from you. Critical Failure The target is pushed 10 feet away from you and knocked prone.', range: '500 feet', target: '1 creature', action: '2' },
  { name: 'Rallying Anthem', level: 2, cantrip: true, focus: true, tradition: 'Bard', book: 'player-core', desc: 'Your song moves allies to protect themselves more effectively. You and all allies in the area gain a +1 status bonus to AC and saving throws, as well as resistance equal to half the spell’s rank to physical damage.', area: '60-foot emanation', action: '1' },
  { name: 'Ranger\'s Bramble', level: 3, focus: true, tradition: 'Ranger', book: 'player-core', desc: 'You cause plants in the area to entangle your foes, with the effects of entangling flora. A creature that critically fails the save takes 2d4 persistent bleed damage in addition to being immobilized. Escaping your bramble doesn’t end the bleed damage.', range: '100 feet', area: '5-foot burst', action: '2' },
  { name: 'Read Fate', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You attempt to learn more about the target’s fate in the short term, usually within the next day for most prosaic creatures, or the next hour or less for someone likely to have multiple rapid experiences, such as someone actively adventuring. You learn a single enigmatic word connected to the creature’s fate in that time frame. Fate is notoriously inscrutable, and the word isn’t necessarily meant to be taken at face value, so the meaning is often clear only in hindsight. The GM rolls a secret DC 6 flat check. If the creature’s fate is too uncertain, or on a failed flat check, the spell yields the word “inconclusive.” Either way, the creature is then temporarily immune for 24 hours.', range: '30 feet', target: '1 creature other than you', action: '2' },
  { name: 'Rebuke Death', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You snatch creatures from the jaws of death, restoring them without the strain of a typical close call. You can spend 1 to 3 actions Casting this Spell, and you can target a number of creatures equal to the actions spent. Each target regains 3d6 Hit Points. If the target had the dying condition, coming back from dying due to this healing doesn’t increase its wounded condition.', target: '1 living creature per action spent to Cast this Spell', area: '20-foot emanation', action: '1-3' },
  { name: 'Restorative Moment', level: 5, focus: true, tradition: 'Witch', book: 'player-core', desc: 'Your patron weaves the threads of time around the target, giving them some of the benefits of a day’s passage. The target decreases the values of any doomed and drained conditions it has by 1 and can immediately attempt one saving throw against each affliction it has with a stage length of 1 day or less. The target is then temporarily immune for 1 day.', range: '30 feet', target: '1 creature', action: '2' },
  { name: 'Retributive Pain', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You vengefully reflect your pain upon your tormentor. The target takes mental damage equal to half the triggering damage.', range: '30 feet', target: 'the triggering creature', action: 'R' },
  { name: 'Rune of Observation', level: 4, focus: true, tradition: 'Wizard', book: 'player-core', desc: 'You inscribe an invisible eye-shaped rune in the air, creating a sensor as clairvoyance. When created, this eye must be in your line of sight. Each time the spell’s duration ends, you can spend 1 Focus Point as a free action to extend the duration for another hour, though as normal, it ends immediately during your next daily preparations.', range: '500 feet', action: '1' },
  { name: 'Safeguard Secret', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You ensure a secret remains safe from prying spies. Choose one piece of information that at least some of the targets know, such as “the location of the stolen treasure” or “the password to enter the guild house.” The spell grants those who know the piece of knowledge you have chosen a +4 status bonus to skill checks (typically Deception checks) to conceal this knowledge, to saving throws against spells that specifically attempt to obtain this knowledge from them, and to effects that would force them to reveal it. If you Cast this Spell again, any previous safeguard secret you had cast ends.', range: '30 feet', target: 'you and any number of willing allies', action: '2' },
  { name: 'Savor the Sting', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You inflict pain upon the target and revel in their anguish. This deals 1d4 mental damage and 1d4 persistent mental damage; the target must attempt a Will save. As long as the target is taking persistent damage from this spell, you gain a +1 status bonus to attack rolls and skill checks against the target. Critical Success The target is unaffected. Success The target takes half damage and no persistent damage. Failure The target takes full initial and persistent damage. Critical Failure The target takes double initial and persistent damage.', damage: '1d4', range: 'touch', target: '1 creature', action: '1', heightened: "(+1) The initial damage increases by 1d4 and the persistent damage increases by 1d4.", heightenStep: 1, heightenDice: '1d4' },
  { name: 'Scholarly Recollection', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'Speaking a short prayer as you gather your thoughts, you’re blessed to find yourself pointed in the right direction. The GM rolls the triggering check twice and uses the better result.', action: 'R' },
  { name: 'Scramble Body', level: 1, focus: true, tradition: 'Wizard', book: 'player-core', desc: 'Your magic throws the creature’s biology into disarray, inducing nausea, fever, and other unpleasant conditions. Success The target is unaffected. Failure The target becomes sickened 1. Critical Failure The target becomes sickened 2 and slowed 1 as long as it’s sickened.', range: '30 feet', target: '1 living creature', action: '2' },
  { name: 'Shared Nightmare', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'Merging minds with the target, you swap distressing visions. One of you will become confused, based on the target’s Will save. Critical Success You are confused for 1 round. Success At the start of your next turn, you spend your first action with the confused condition, then act normally. Failure The target spends the first action of each of its turns confused. The duration is 1 minute. Critical Failure The target is confused. The duration is 1 minute.', range: '30 feet', target: '1 creature', action: '2' },
  { name: 'Shifting Form', level: 4, focus: true, tradition: 'Wizard', book: 'player-core', desc: 'You change your body to better suit the moment. You gain one of the following abilities of your choice. You can Dismiss this spell. You gain a 20-foot status bonus to your Speed. You gain a climb or swim Speed equal to half your Speed. You gain darkvision. You gain a pair of claws. These are agile finesse unarmed attacks that deal 1d8 slashing damage. You gain scent 60 feet (imprecise).', action: '1' },
  { name: 'Shroud of Night', level: 1, cantrip: true, focus: true, tradition: 'Witch', book: 'player-core', desc: 'Your patron blankets the target’s eyes in darkness. If you cast this hex on a willing ally (for instance, one with light blindness), the ally can choose which result it gets without rolling. Success The target is unaffected. Failure The target is shrouded in murky darkness. It treats bright light as dim light, and unless it has greater darkvision, all creatures are concealed to it.', range: '30 feet', target: '1 creature', action: '1' },
  { name: 'Song of Marching', level: 3, cantrip: true, focus: true, tradition: 'Bard', book: 'player-core', desc: 'You maintain a brisk performance that keeps allies on the move. You and your allies in the area can Hustle for the spell’s duration, in addition to your other exploration activities (your exploration activity is Sustaining this spell). You and your allies then become temporarily immune for 1 day. If you enter an encounter while performing this song, you can use your Performance modifier for the initiative roll. You and your affected allies also receive a +1 status bonus to that initiative roll.', area: '60-foot emanation', action: '1' },
  { name: 'Song of Strength', level: 1, cantrip: true, focus: true, tradition: 'Bard', book: 'player-core', desc: 'You bolster your allies’ physical strength with a hearty exhortation. You and your allies gain a +1 status bonus to Athletics checks and to their DCs against Athletics skill actions such as Disarm, Reposition, Shove, and Trip.', area: '60-foot emanation', action: '1' },
  { name: 'Soothing Ballad', level: 7, focus: true, tradition: 'Bard', book: 'player-core', desc: 'You draw upon your muse to soothe your allies. Choose one of the following three effects: The spell attempts to counteract fear effects on the targets. The spell attempts to counteract effects imposing paralysis on the targets. The spell restores 7d8 Hit Points to the targets.', range: '30 feet', target: 'you and up to 9 allies', action: '2' },
  { name: 'Soothing Mist', level: 2, focus: true, tradition: 'Ranger', book: 'player-core', desc: 'You call forth a magical mist that envelops a creature. The mist restores 2d8 Hit Points to a target living creature and ends one source of persistent acid, bleed, fire, poison, or void damage affecting it. If the creature is taking persistent damage from multiple sources, you select which one is removed. Against an undead target, you deal 2d8 vitality damage (basic Fortitude save); if it fails the save, it also takes 2 persistent vitality damage.', damage: '2d8', range: '30 feet', target: '1 willing living creature or 1 undead creature', action: '2', heightened: "(+1) The amount of healing (or damage to an undead target) increases by 1d8, and the persistent vitality damage to an undead creature increases by 1.", heightenStep: 1, heightenDice: '1d8' },
  { name: 'Soothing Words', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You attempt to calm the target by uttering soothing words in a calm and even tone. The target gains a +1 status bonus to Will saving throws. This bonus increases to +2 against emotion effects. In addition, when you Cast this Spell, you can attempt to counteract one emotion effect on the target.', range: '30 feet', target: '1 ally', duration: '1 minute', action: '1', heightened: "(5th) The bonus to saves increases to +2, or +3 against emotion effects.", heightenAt: [5] },
  { name: 'Spiral of Horrors', level: 4, focus: true, tradition: 'Wizard', book: 'player-core', desc: 'Shades and spirits howl and whirl around you in a display that strikes fear into the hearts of all who witness it. Enemies in the area are frightened 1 and can’t reduce their frightened value below 1 for the spell’s duration.', area: '30-foot emanation', action: '2' },
  { name: 'Stoke the Heart', level: 1, cantrip: true, focus: true, tradition: 'Witch', book: 'player-core', desc: 'Your patron fills a creature with fervor, empowering their blows. The target gains a +2 status bonus to damage rolls.', range: '30 feet', target: '1 creature', action: '1', heightened: "(+2) The status bonus to damage increases by 1.", heightenStep: 2 },
  { name: 'Storm Lord', level: 9, focus: true, tradition: 'Druid', book: 'player-core', desc: 'The sky above you darkens in a matter of moments, swirling with ominous clouds punctuated by flashes of lighting. When you Cast the Spell and the first time you Sustain it each turn on subsequent rounds, select one of the following effects to occur in the area. Calm No additional effect. Fog Heavy fog rolls in, with the effects of mist. Rain Torrential rain falls from the sky, dousing ordinary flames. Creatures in the area take a –2 circumstance penalty to Acrobatics and Perception checks. Wind Powerful winds buffet the area in all directions. Ranged attacks take a –4 circumstance penalty, and the area is difficult terrain for flying creatures. In addition, once per round you can use a single action, which has the concentrate and manipulate traits, to call down a bolt of lightning, striking any target in range that you can see. You deal 10d6 electricity damage to the target; it must attempt a basic Reflex save. On a failure, it is also deafened for 1 round.', damage: '10d6', area: '100-foot emanation', action: '2' },
  { name: 'Stormwind Flight', level: 4, focus: true, tradition: 'Druid', book: 'player-core', desc: 'Powerful winds carry you through the air, giving you a fly Speed equal to your Speed. When this spell’s duration would end, if you’re still flying, you float to the ground, as gentle landing.', action: '2' },
  { name: 'Sudden Shift', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You swiftly move from a dangerous spot and veil yourself. You Step and become concealed.', duration: 'until the end of your next turn', action: 'R' },
  { name: 'Sweet Dream', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'With soothing words, you lull the target into an enchanting dream. When you Cast the Spell, the target falls unconscious if it wasn’t already. While unconscious, it experiences a dream of your choice, though lucidly enough it can wake when it pleases. If it wakes up before 1 minute of sleep has passed, the spell ends. Dream of Insight +1 status bonus to Intelligence-based skill checks Dream of Glamor +1 status bonus to Charisma-based skill checks Dream of Voyaging +5-foot status bonus to Speed. If you Cast this Spell again, any previous sweet dream you cast ends.', range: '30 feet', target: '1 willing creature', duration: '1 hour', action: '2', heightened: "(4th) The bonus for a dream of insight or glamor is +2. (7th) The bonus for a dream of insight or glamor is +3.", heightenAt: [4, 7] },
  { name: 'Symphony of the Unfettered Heart', level: 5, focus: true, tradition: 'Bard', book: 'player-core', desc: 'Your symphony lifts listeners from their worldly concerns. Attempt a Performance check to counteract an effect applying one of the following conditions to the target: grabbed, immobilized, paralyzed, restrained, slowed, or stunned. If you fail, you can’t target the same effect on the target for 1 day. Use the condition’s source to determine the counteract DC (for example, the Escape DC for grabbed).', range: '30 feet', target: 'you or 1 ally', action: '2' },
  { name: 'Take its Course', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'When someone has overindulged, you can hasten them past the worst of their affliction or intensify their misery. This spell attempts to progress a disease affliction, a poison affliction, or persistent poison damage affecting the target. If the target is affected by more than one of these, choose from among those you are aware of; otherwise, the GM chooses randomly. An unwilling target can attempt a Will save to negate take its course. The effect of this spell depends on whether you’re attempting to end an affliction or persistent poison damage, and whether you are attempting to help or hinder the target’s recovery. Affliction The target immediately attempts its next saving throw against the affliction. You can grant the creature your choice of a +2 status bonus or a –2 status penalty to its saving throw against the affliction. Persistent Poison You can cause the target to take the persistent poison damage immediately when you Cast this Spell (in addition to taking it at the end of its next turn). Whether or not you do so, the target attempts an additional flat check against the persistent poison damage. You can set the DC of that flat check to 5 or 20 instead of the normal DC.', range: 'touch', target: '1 creature', action: '2' },
  { name: 'Tempest Surge', level: 1, focus: true, tradition: 'Druid', book: 'player-core', desc: 'You surround a foe in a swirling storm of violent winds, roiling clouds, and crackling lightning. The storm deals 1d12 electricity damage to the target with a basic Reflex save. On a failure, the target also is clumsy 2 for 1 round.', damage: '1d12', range: '30 feet', target: '1 creature', action: '2', heightened: "(+1) The initial damage increases by 1d12.", heightenStep: 1, heightenDice: '1d12' },
  { name: 'Tempt Fate', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You twist the forces of fate to make a moment dire or uneventful, with no in-between. The target gains a +1 status bonus to the triggering saving throw. If the saving throw’s result is a success, it becomes a critical success. If it’s a failure, it becomes a critical failure, and the critical failure can’t be reduced by abilities that usually reduce critical failure. If the triggering ability did not have both a critical success and critical failure condition, tempt fate fails, but you don’t expend the Focus Point for Casting this Spell.', range: '120 feet', target: 'the triggering creature', action: 'R' },
  { name: 'Terrain Transposition', level: 5, focus: true, tradition: 'Ranger', book: 'player-core', desc: 'You mystically transpose your current location with another. While in a wilderness environment, you transport yourself and items you’re holding to a clear space you can see within range. If you have Favored Terrain and both your starting and ending position are in your favored terrain, the range increases to 180 feet. If you have an animal companion and it is adjacent to you, you can transport it along with you to an adjacent open space, but if this spell would bring any other creature with you, even in an extradimensional container, the spell is lost.', range: '90 feet', action: '2' },
  { name: 'Tidal Surge', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You call forth a tremendous wave to move the target either in a body of water or on the ground. You move the target up to 10 feet in any direction along the ground or 20 feet through a body of water. An unwilling target can attempt a Fortitude save, and it avoids being moved if it succeeds.', range: '60 feet', target: '1 creature', action: '1' },
  { name: 'Touch of Obedience', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'Your imperious touch erodes the target’s willpower, making it easier to control. The target attempts a Will save. Regardless of the result, it’s then temporarily immune for 1 hour. Critical Success The target is unaffected. Success The target is stupefied 1 until the end of your next turn. Failure The target is stupefied 2 until the end of your next turn. Critical Failure The target is stupefied 2 for 1 minute and is forced to its knees, becoming prone.', range: 'touch', target: '1 living creature', duration: 'varies', action: '1' },
  { name: 'Touch of the Moon', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'When you touch the target, a symbol of the moon appears on its forehead, glowing with soft moonlight. The target glows with dim light in a 20-foot radius. It also gets a benefit based on a phase of the moon, starting with the new moon and changing to the next phase at the end of each of its turns. New Moon The target receives no benefit. Waxing Moon The target gains a +1 status bonus to attack rolls and a +4 status bonus to damage rolls. Full Moon The target gains a +1 status bonus to attack rolls, AC, and saves, and a +4 status bonus to damage. Waning Moon The target gains a +1 status bonus to AC and saving throws. After this phase, return to the new moon.', range: 'touch', target: '1 creature', action: '1' },
  { name: 'Touch of Undeath', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You attack the target’s life force with undeath, dealing 1d6 void damage. The target must attempt a Fortitude save. Critical Success The target is unaffected. Success The target takes half damage. Failure The target takes full damage, and vitality effects heal it only half as much as normal for 1 round. Critical Failure The target takes double damage, and vitality effects heal it only half as much as normal for 1 minute.', damage: '1d6', range: 'touch', target: '1 living creature', duration: 'varies', action: '1', heightened: "(+1) The damage increases by 1d6.", heightenStep: 1, heightenDice: '1d6' },
  { name: 'Traveler\'s Transit', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You add power to your muscles, allowing you to swim or climb walls with ease. When you Cast this Spell, you gain either a climb Speed or a swim Speed. The Speed is equal to your land Speed.', action: '2' },
  { name: 'Trickster\'s Twin', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You rarely settle for being in just one place. Choose a location within 100 feet of the target that the target can see. You create an illusion of yourself there that only it can see and that mimics all your actions. The target must attempt a Will save. Critical Success The target is unaffected. Success The target believes you’re in the designated location and can’t see you in your actual location. The target automatically disbelieves the illusion when you use an action that doesn’t make sense in the illusion’s position, or if the target attacks, touches, Seeks, or otherwise engages with the illusion. If you use a hostile action against the target, the spell ends. Failure As success, but the target must succeed at a Will save to disbelieve the illusion when one of the listed events occurs. Critical Failure As success, but the target must critically succeed at a Will save to disbelieve when one of the listed events occurs.', range: '30 feet', target: '1 creature', action: '2' },
  { name: 'Triple Time', level: 2, cantrip: true, focus: true, tradition: 'Bard', book: 'player-core', desc: 'Your music sets a fast pace. You and all allies in the area gain a +10-foot status bonus to all Speeds for 1 round.', area: '60-foot emanation', action: '1' },
  { name: 'Unimpeded Stride', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'Divine grace ensure that nothing can keep you prisoner or hold you back. You immediately escape from every magical effect that has you immobilized or grabbed unless the effect is of a higher rank than your unimpeded stride spell. You then Stride. During this movement, you ignore difficult terrain and any circumstance or status penalties to your Speed.', action: '1' },
  { name: 'Unity', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You put up a united defense. Each ally can use your saving throw modifier instead of its own against the triggering spell. Each ally decides individually which modifier to use.', range: '30 feet', target: 'each ally targeted by the triggering spell', action: 'R' },
  { name: 'Untamed Form', level: 1, focus: true, tradition: 'Druid', book: 'player-core', desc: 'You reach within for a different part of yourself, and you set it free, transforming your body into another form. You polymorph into any form listed in pest form, which lasts 10 minutes. All other untamed form shapes last 1 minute. You can add more shapes to your untamed form list with druid feats; your feat might grant you some or all of the shapes from a given polymorph spell. When you transform into a shape granted by a spell, you gain all the effects of the shape you chose from a version of the spell heightened to untamed form’ s rank. Untamed form allows you to use your own shapeshifting training more easily than most polymorph spells. When you choose to use your own attack modifier while polymorphed instead of the form’s default attack modifier, you gain a +2 status bonus to your attack rolls.', duration: 'varies', action: '2', heightened: "(2nd) You can transform into shapes listed in animal form.", heightenAt: [2] },
  { name: 'Untamed Shift', level: 1, focus: true, tradition: 'Druid', book: 'player-core', desc: 'You transform just a part of your body. Choose any one effect that matches an untamed order feat you have. Untamed Form Your hands transform into incredibly sharp claws. Untamed claws are an unarmed attack, have the agile and finesse traits, and deal 1d6 slashing damage. You can still hold and use items with your hands while they’re transformed by this spell, but you must have a hand free to attack with it. Insect Shape Your mouth becomes deadly jaws. Untamed jaws are an unarmed attack that deal 1d8 piercing damage. Elemental Shape You shift your body to be partially composed of elemental matter, granting you resistance 5 to critical hits and precision damage. Plant Shape Your arms become long vines, increasing your reach to 10 feet (or 15 feet with a reach weapon). Soaring Shape You must cast untamed shift using 2 actions for this benefit. You grow wings from your back, gaining a fly Speed of 30 feet.', duration: '1 minute', action: '1-2', heightened: "(6th) You can choose up to two effects from the list. Untamed claws leave terrible, ragged wounds that also deal 2d6 persistent bleed damage on a hit, and untamed jaws are envenomed, also dealing 2d6 persistent poison damage on a hit. (10th) You can choose up to three effects from the list. Untamed claws deal 4d6 persistent bleed damage on a hit, and untamed jaws deal 4d6 persistent poison damage on a hit.", heightenAt: [6, 10] },
  { name: 'Uplifting Overture', level: 1, cantrip: true, focus: true, tradition: 'Bard', book: 'player-core', desc: 'Your performance makes allies feel they can succeed at anything. This counts as having prepared to Aid your ally on a skill check of your choice. When you later use the Aid reaction, you can roll Performance instead of the normal skill check, and if you roll a failure, you get a success instead. If you are legendary in Performance, you automatically critically succeed. The GM might rule that you can’t use this ability if the act of encouraging your ally would interfere with the skill check (such as a check to Sneak quietly or maintain a disguise).', range: '60 feet', target: '1 ally', action: '1' },
  { name: 'Veil of Confidence', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You surround yourself in confidence. You reduce your current frightened condition by 1, and whenever you would become frightened during the duration, reduce the amount by 1. If you critically fail a save against a fear effect, veil of confidence reduces your frightened value from that effect, and then ends.', duration: '1 minute', action: '1' },
  { name: 'Veil of Dreams', level: 1, focus: true, tradition: 'Witch', book: 'player-core', desc: 'Your patron draws the target into a drowsy state, causing daydreams and sluggishness. The target must attempt a Will save. Critical Success The target is unaffected. Success The target takes a –1 status penalty to Perception, attack rolls, and Will saves. This penalty increases to –2 for Will saves against sleep effects. Failure As success, and any time the target uses a concentrate action, it must succeed at a DC 5 flat check or the action is disrupted.', range: '30 feet', target: '1 creature', duration: 'sustained up to 1 minute', action: '1' },
  { name: 'Vibrant Thorns', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'Your body sprouts brambly thorns that thrive on life magic. Adjacent creatures that hit you with a melee attack, as well as creatures that hit you with unarmed attacks, take 1 piercing damage each time they do. Anytime you cast a vitality spell, the thorns’ damage increases to 1d6 until the start of your next turn.', duration: '1 minute', action: '1', heightened: "(+1) The damage increases by 1, or 1d6 after you cast a vitality spell.", heightenStep: 1 },
  { name: 'Waking Nightmare', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You fill the creature’s mind with a terrifying vision. The target must attempt a Will save. A creature frightened by this spell takes 1 additional mental damage each time it’s hit by a Strike. Critical Success The target is unaffected. Success The target is frightened 1. Failure The target is frightened 2. If it’s asleep, it wakes up and is paralyzed for 1 round. Critical Failure As failure, but frightened 3.', range: '30 feet', target: '1 creature', duration: 'varies', action: '2', heightened: "(+1) The mental damage increases by 1.", heightenStep: 1 },
  { name: 'Weapon Surge', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'Holding your weapon aloft, you fill it with divine energy. On your next Strike with that weapon before the start of your next turn, you gain a +1 status bonus to the attack roll, the weapon deals an additional 1d6 spirit damage, and the Strike gains the sanctified trait. Weapon surge ends once you complete this Strike or the weapon leaves your possession.', range: 'touch', target: '1 weapon you\'re wielding', duration: 'until the start of your next turn', damage: '1d6', action: '1', heightened: "(5th) The attack deals 2d6 additional spirit damage. (9th) The attack deals 3d6 additional spirit damage.", heightenAt: [5, 9] },
  { name: 'Whispering Quiet', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You suppress sound in an area, preventing anyone from giving away valuable secrets. This doesn’t prevent those in the area from talking or Casting a Spell, but no creature more than 5 feet away can hear its voice without succeeding at a Perception check against your spell DC, which might interfere with auditory or linguistic effects as well as communication. Other sounds created in the area are muffled to a similar volume unless that sound is created by an effect with the sonic trait.', range: '60 feet', area: '15-foot burst', duration: '1 minute', action: '2' },
  { name: 'Wilding Word', level: 1, cantrip: true, focus: true, tradition: 'Witch', book: 'player-core', desc: 'Your patron’s majesty—or their displeasure—comes in a growl from your throat, making other creatures reluctant to harm you. The target must attempt a Will save; if the creature is an animal, fungus, or plant, it takes a –1 circumstance penalty to its save. Critical Success The target is unaffected. Success When the target attempts an attack roll or skill check that would harm you, it takes a –2 status penalty to its roll. Failure As success, but the target also becomes sickened 1 each time it damages you. Critical Failure As failure, but the sickened value is 2.', range: '30 feet', target: '1 creature', action: '1' },
  { name: 'Word of Freedom', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You utter a liberating word of power that frees a creature. You suppress one of the following conditions of your choice: confused, frightened, grabbed, paralyzed, or restrained. The target isn’t affected by the chosen condition, and if you suppress the grabbed or restrained condition, the target automatically breaks free from the grab or restraint when you Cast the Spell. If you don’t remove the effect that provided the condition, the condition returns after the spell ends. For example, if a spell was making the target confused for 1 minute, word of freedom would let the target act normally for a round, but the confused condition would return afterward.', range: '30 feet', target: '1 creature', action: '1' },
  { name: 'Word of Truth', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You speak a statement that you believe to be true and that is free of any attempt to deceive through twisting words, omission, and so on. The statement must be 25 words or fewer. A symbol of your deity glows above your head and lasts for the spell’s duration, and anyone who sees you and hears you speak knows instinctively that you believe what you say is true. This assurance of honesty grants you a +2 status bonus to Diplomacy checks as long as the symbol persists. You can Dismiss the spell, and if you say something that you don’t believe is entirely true, the spell ends before you complete your statement.', duration: 'sustained up to 1 minute', action: '1' },
  { name: 'Zeal for Battle', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You stoke the righteous anger within yourself and an ally. You and the target ally each roll a d20 and use the higher result for both your initiative rolls. You each still use your own Perception modifier or other statistic to determine your results.', range: '10 feet', target: 'you and the triggering ally', action: 'R' },
];
